from pathlib import Path
import re

p = Path('index.html')
s = p.read_text()

def replace_once(old, new, label):
    global s
    count = s.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    s = s.replace(old, new, 1)

# 1) Pill completion indicator styling. Replace the old decorative dot only.
replace_once('''    .pill::before {\n      content: "";\n      width: 10px;\n      height: 10px;\n      border-radius: 50%;\n      background: rgba(245, 196, 0, 0.72);\n      margin-right: 12px;\n      flex: 0 0 auto;\n    }\n''', '''    .pill-label {\n      min-width: 0;\n      flex: 1 1 auto;\n    }\n\n    .pill-progress-mark {\n      width: 20px;\n      height: 20px;\n      margin-left: 12px;\n      border-radius: 50%;\n      flex: 0 0 auto;\n      position: relative;\n    }\n\n    .pill-progress-ring {\n      background: conic-gradient(var(--evia-yellow) var(--pill-progress, 0deg), rgba(245, 196, 0, 0.18) 0);\n    }\n\n    .pill-progress-ring::after {\n      content: "";\n      position: absolute;\n      inset: 3px;\n      border-radius: 50%;\n      background: rgba(250, 249, 242, 0.98);\n    }\n\n    .pill-progress-tick {\n      display: grid;\n      place-items: center;\n      background: var(--evia-yellow);\n      color: #fff;\n      font-size: 13px;\n      line-height: 1;\n      font-weight: 700;\n    }\n''', 'pill completion CSS')

# 2) Persistent completion state, based only on a fully completed leaf evidence sequence.
replace_once('''    let completionContext = null;\n    let learningEntries = loadLearningEntries();\n    let learnerProfile = loadLearnerProfile();\n''', '''    let completionContext = null;\n    let learningEntries = loadLearningEntries();\n    let completedEvidencePaths = loadCompletedEvidencePaths();\n    let learnerProfile = loadLearnerProfile();\n''', 'completion state declaration')

# 3) Add completion helpers and render rings/ticks in every course pill.
old_render = '''    function renderPills(floatIn = false) {\n      pillStack.innerHTML = '';\n      currentItems.forEach((item, index) => {\n        const pill = document.createElement('div');\n        pill.className = `pill${floatIn ? ' float-in' : ''}`;\n        pill.dataset.index = String(index);\n        pill.setAttribute('role', 'button');\n        pill.setAttribute('tabindex', '0');\n        pill.textContent = item.label;\n        pillStack.appendChild(pill);\n      });\n\n      if (floatIn) {\n        requestAnimationFrame(() => {\n          requestAnimationFrame(() => {\n            pillStack.querySelectorAll('.pill').forEach((pill) => pill.classList.remove('float-in'));\n          });\n        });\n      }\n      updateBackButton();\n    }\n'''
new_render = '''    function evidencePathKey(path) {\n      return JSON.stringify((Array.isArray(path) ? path : []).map(cleanText));\n    }\n\n    function loadCompletedEvidencePaths() {\n      try {\n        const saved = JSON.parse(localStorage.getItem('eviaCompletedEvidencePathsV1') || '[]');\n        return new Set(Array.isArray(saved) ? saved.filter((item) => typeof item === 'string') : []);\n      } catch (error) {\n        return new Set();\n      }\n    }\n\n    function saveCompletedEvidencePaths() {\n      try {\n        localStorage.setItem('eviaCompletedEvidencePathsV1', JSON.stringify([...completedEvidencePaths]));\n      } catch (error) {\n        // Completion still remains active for this session.\n      }\n    }\n\n    function markEvidencePathComplete(path) {\n      const key = evidencePathKey(path);\n      if (key === '[]') return;\n      completedEvidencePaths.add(key);\n      saveCompletedEvidencePaths();\n    }\n\n    function leafEvidencePaths(node, prefix) {\n      const path = [...prefix, cleanText(node?.label)];\n      const children = Array.isArray(node?.children) ? node.children.filter(Boolean) : [];\n      if (!children.length) return [path];\n      return children.flatMap((child) => leafEvidencePaths(child, path));\n    }\n\n    function pillCompletion(node, prefix) {\n      const leaves = leafEvidencePaths(node, prefix);\n      const total = leaves.length || 1;\n      const completed = leaves.reduce((sum, path) => sum + (completedEvidencePaths.has(evidencePathKey(path)) ? 1 : 0), 0);\n      return { completed, total, complete: completed >= total };\n    }\n\n    function renderPills(floatIn = false) {\n      pillStack.innerHTML = '';\n      const prefix = getLabelsForPath(menuPath);\n      currentItems.forEach((item, index) => {\n        const pill = document.createElement('div');\n        pill.className = `pill${floatIn ? ' float-in' : ''}`;\n        pill.dataset.index = String(index);\n        pill.setAttribute('role', 'button');\n        pill.setAttribute('tabindex', '0');\n\n        const label = document.createElement('span');\n        label.className = 'pill-label';\n        label.textContent = item.label;\n        pill.appendChild(label);\n\n        const progress = pillCompletion(item, prefix);\n        const mark = document.createElement('span');\n        mark.setAttribute('aria-hidden', 'true');\n        if (progress.complete) {\n          mark.className = 'pill-progress-mark pill-progress-tick';\n          mark.textContent = '✓';\n        } else {\n          mark.className = 'pill-progress-mark pill-progress-ring';\n          mark.style.setProperty('--pill-progress', `${(progress.completed / progress.total) * 360}deg`);\n        }\n        pill.appendChild(mark);\n        pill.setAttribute('aria-label', progress.complete ? `${item.label}, complete` : `${item.label}, ${progress.completed} of ${progress.total} complete`);\n        pillStack.appendChild(pill);\n      });\n\n      if (floatIn) {\n        requestAnimationFrame(() => {\n          requestAnimationFrame(() => {\n            pillStack.querySelectorAll('.pill').forEach((pill) => pill.classList.remove('float-in'));\n          });\n        });\n      }\n      updateBackButton();\n    }\n'''
replace_once(old_render, new_render, 'pill rendering with completion')

# 4) Correct evidence routing. Ignore conditional wording such as "If video is not practical" and support alternatives.
old_routing = '''    function captureKindFromText(value, fallbackType = 'text') {\n      const text = cleanText(value).toLowerCase();\n      if (/\\bvideo\\b/.test(text)) return 'video';\n      if (/\\bphotos?\\b|\\bcamera\\b|\\bimages?\\b/.test(text)) return 'photo';\n      if (/\\baudio\\b|\\bvoice\\b|\\bmicrophone\\b|\\breflection\\b/.test(text)) return 'audio';\n      if (/\\bwritten\\b|\\bwrite\\b|\\btext\\b|\\bstatement\\b|\\btyping\\b/.test(text)) return 'text';\n      if (fallbackType === 'camera') return 'photo';\n      if (fallbackType === 'audio') return 'audio';\n      return fallbackType === 'video' ? 'video' : 'text';\n    }\n\n    function captureKindsFromDetail(detail, fallbackType = 'text') {\n      const source = `${detail?.displayType || ''} ${detail?.label || ''} ${detail?.instruction || ''}`;\n      const additiveParts = source.split(/\\b(?:plus|then|followed by)\\b/i).map((part) => part.trim()).filter(Boolean);\n      const parts = additiveParts.length > 1 ? additiveParts : [source];\n      const kinds = parts.map((part) => captureKindFromText(part, '')).filter(Boolean);\n      return kinds.length ? kinds : [captureKindFromText(source, fallbackType)];\n    }\n'''
new_routing = '''    function stripEvidenceConditionals(value) {\n      return cleanText(value)\n        .replace(/\\bif\\s+(?:a\\s+)?video\\s+is\\s+not\\s+practical\\b[:,]?\\s*/ig, '')\n        .replace(/\\bif\\s+(?:a\\s+)?video\\s+(?:is\\s+)?not\\s+possible\\b[:,]?\\s*/ig, '')\n        .trim();\n    }\n\n    function captureKindFromText(value, fallbackType = '') {\n      const text = stripEvidenceConditionals(value).toLowerCase();\n      if (/\\bwitness\\s+(?:testimony|statement)\\b|\\btestimony\\b/.test(text)) return 'witness';\n      const hasAudio = /\\baudio\\b|\\bvoice\\b|\\bmicrophone\\b|\\breflection\\b/.test(text);\n      const hasWritten = /\\bwritten\\b|\\bwrite\\b|\\btext\\b|\\btyping\\b/.test(text);\n      if (hasAudio && hasWritten && /\\bor\\b/.test(text)) return 'audio-or-text';\n      if (/\\bphotos?\\b|\\bcamera\\b|\\bimages?\\b/.test(text)) return 'photo';\n      if (/\\bvideo\\b/.test(text)) return 'video';\n      if (hasAudio) return 'audio';\n      if (hasWritten) return 'text';\n      if (fallbackType === 'camera') return 'photo';\n      if (fallbackType === 'audio') return 'audio';\n      if (fallbackType === 'video') return 'video';\n      if (fallbackType === 'witness') return 'witness';\n      return fallbackType === 'text' ? 'text' : '';\n    }\n\n    function captureKindsFromDetail(detail, fallbackType = 'text') {\n      const source = stripEvidenceConditionals(`${detail?.label || ''} ${detail?.instruction || ''}`);\n      const additiveParts = source.split(/\\b(?:plus|then|followed by)\\b/i).map((part) => part.trim()).filter(Boolean);\n      const parts = additiveParts.length > 1 ? additiveParts : [source];\n      const kinds = parts.map((part) => captureKindFromText(part, '')).filter(Boolean);\n      if (kinds.length) return kinds;\n      const displayKind = captureKindFromText(detail?.displayType || '', '');\n      return displayKind ? [displayKind] : [captureKindFromText(source, fallbackType) || 'text'];\n    }\n'''
replace_once(old_routing, new_routing, 'evidence routing')

# 5) Avoid trying to quantity-expand witness or audio-or-written choices.
replace_once("""      const words = type === 'photo' ? 'photos?|images?'\n        : type === 'video' ? 'videos?|recordings?'\n        : type === 'audio' ? 'audio|recordings?|voice notes?'\n        : 'written|text|statements?|entries';\n""", """      if (type === 'witness' || type === 'audio-or-text') return 1;\n      const words = type === 'photo' ? 'photos?|images?'\n        : type === 'video' ? 'videos?|recordings?'\n        : type === 'audio' ? 'audio|recordings?|voice notes?'\n        : 'written|text|statements?|entries';\n""", 'capture quantity special types')

# 6) Correct status labels and add the approved witness-file and audio/written chooser surfaces.
replace_once("""      const typeName = step.type === 'photo' ? 'Photo' : step.type === 'video' ? 'Video' : step.type === 'audio' ? 'Audio' : 'Written evidence';\n""", """      const typeName = step.type === 'photo' ? 'Photo'\n        : step.type === 'video' ? 'Video'\n        : step.type === 'audio' ? 'Audio'\n        : step.type === 'witness' ? 'Witness testimony'\n        : step.type === 'audio-or-text' ? 'Audio or written evidence'\n        : 'Written evidence';\n""", 'capture status labels')

insert_before = '''    function runCaptureStep(){const step=capturePlan[captureStepIndex],sessionId=captureSessionId;if(!step)return;if(step.type==='photo')openPhotoCapture(step,sessionId);else if(step.type==='video')openVideoCapture(step,sessionId);else if(step.type==='audio')openAudioCapture(step,sessionId);else openTextCapture(step,sessionId)}\n'''
replacement = '''    function openAudioOrTextChoice(step, sessionId) {\n      stopCapture(); captureMode='choice';\n      evidenceTop.innerHTML='<div class="capture-surface"><div class="audio-panel"><button class="capture-button" id="chooseAudioEvidence" type="button">Record audio</button><button class="capture-button" id="chooseWrittenEvidence" type="button">Write evidence</button><div class="capture-status" id="captureStatus"></div></div></div>';\n      evidenceTop.style.gridTemplateRows='1fr'; updateBackButton(); fitUiText(); showCaptureStatus('Choose audio or written evidence.');\n      document.getElementById('chooseAudioEvidence').addEventListener('click',()=>{if(sessionId!==captureSessionId)return;capturePlan[captureStepIndex]={...step,type:'audio'};runCaptureStep()});\n      document.getElementById('chooseWrittenEvidence').addEventListener('click',()=>{if(sessionId!==captureSessionId)return;capturePlan[captureStepIndex]={...step,type:'text'};runCaptureStep()});\n    }\n\n    function witnessFileExtension(file) {\n      const name = cleanText(file?.name);\n      const match = name.match(/\\.([a-z0-9]{1,8})$/i);\n      if (match) return match[1].toLowerCase();\n      const mime = cleanText(file?.type).toLowerCase();\n      if (/pdf/.test(mime)) return 'pdf';\n      if (/wordprocessingml/.test(mime)) return 'docx';\n      if (/msword/.test(mime)) return 'doc';\n      if (/png/.test(mime)) return 'png';\n      if (/jpe?g/.test(mime)) return 'jpg';\n      if (/text\\//.test(mime)) return 'txt';\n      return 'file';\n    }\n\n    async function saveWitnessFile(file) {\n      const createdAt = new Date().toISOString();\n      const context = captureEvidenceContext('witness');\n      const method = context.method;\n      const label = context.evidenceLabel;\n      const compactDate = createdAt.replace(/[-:]/g, '').replace(/\\..+/, '').replace('T', '-');\n      const entry = {\n        id: `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,\n        createdAt,\n        type: 'witness',\n        mimeType: file.type || 'application/octet-stream',\n        fileName: `${compactDate}-${safeFilename(label)}.${witnessFileExtension(file)}`,\n        originalFileName: cleanText(file.name),\n        path: context.path.slice(),\n        evidenceLabel: label,\n        methodHeading: method.heading,\n        methodLabel: method.label,\n        requirements: context.requirements,\n        learner: context.learner || officialLearnerProfile(),\n        blob: file\n      };\n      await addPortfolioEntry(entry);\n      updateArchBars().catch(() => {});\n      return entry;\n    }\n\n    function openWitnessImport(step, sessionId) {\n      stopCapture(); captureMode='witness';\n      evidenceTop.innerHTML='<div class="capture-surface"><div class="audio-panel"><button class="capture-button" id="importWitnessFile" type="button">Import witness file</button><input id="witnessFileInput" type="file" hidden><div class="capture-status" id="captureStatus"></div></div></div>';\n      evidenceTop.style.gridTemplateRows='1fr'; updateBackButton(); fitUiText(); showCaptureStatus('Witness testimony can be imported as a file.');\n      const input=document.getElementById('witnessFileInput');\n      document.getElementById('importWitnessFile').addEventListener('click',()=>input.click());\n      input.addEventListener('change',async()=>{\n        const file=input.files?.[0]; if(!file||sessionId!==captureSessionId)return;\n        try{await saveWitnessFile(file);showCaptureStatus('Witness file imported.');await completeCaptureStep(sessionId)}catch(error){showCaptureStatus('Could not import this witness file.')}\n      });\n    }\n\n    function runCaptureStep(){const step=capturePlan[captureStepIndex],sessionId=captureSessionId;if(!step)return;if(step.type==='photo')openPhotoCapture(step,sessionId);else if(step.type==='video')openVideoCapture(step,sessionId);else if(step.type==='audio')openAudioCapture(step,sessionId);else if(step.type==='audio-or-text')openAudioOrTextChoice(step,sessionId);else if(step.type==='witness')openWitnessImport(step,sessionId);else openTextCapture(step,sessionId)}\n'''
replace_once(insert_before, replacement, 'witness and choice capture')

# 7) Ensure Naxos witness methods keep their identity instead of falling through to text.
replace_once("""    function naxosCaptureType(value) {\n      const text = cleanText(value).toLowerCase();\n      if (/video|photo|camera/.test(text)) return 'camera';\n      if (/audio|voice|reflection|microphone/.test(text)) return 'audio';\n      return 'text';\n    }\n""", """    function naxosCaptureType(value) {\n      const text = cleanText(value).toLowerCase();\n      if (/witness|testimony/.test(text)) return 'witness';\n      if (/video|photo|camera/.test(text)) return 'camera';\n      if (/audio|voice|reflection|microphone/.test(text)) return 'audio';\n      return 'text';\n    }\n""", 'Naxos witness type')

# 8) Mark completion only when the entire required evidence sequence reaches its completion point.
replace_once("""    async function completeEvidenceExperience(){\n      completionContext={path:activeEvidencePath.slice(),label:activeEvidencePath[activeEvidencePath.length-1]||activeEvidence?.label||'Evidence'};\n      closeEvidence();resetPills();screen.classList.add('active','completion-open');screen.classList.remove('pills-ready','evidence-ready');reflectionActions.hidden=true;learnReflectionBox.hidden=true;learnReflectionText.value='';learnReflectionStatus.textContent='';updateBackButton();\n""", """    async function completeEvidenceExperience(){\n      completionContext={path:activeEvidencePath.slice(),label:activeEvidencePath[activeEvidencePath.length-1]||activeEvidence?.label||'Evidence'};\n      markEvidencePathComplete(completionContext.path);\n      closeEvidence();resetPills();screen.classList.add('active','completion-open');screen.classList.remove('pills-ready','evidence-ready');reflectionActions.hidden=true;learnReflectionBox.hidden=true;learnReflectionText.value='';learnReflectionStatus.textContent='';updateBackButton();\n""", 'mark completed leaf')

# Guardrails: preserve evidence card/camera positioning and existing major systems.
required = [
    "function stripEvidenceConditionals(value)",
    "return 'audio-or-text';",
    "return 'witness';",
    "function openWitnessImport(step, sessionId)",
    "Import witness file",
    "function pillCompletion(node, prefix)",
    "pill-progress-ring",
    "pill-progress-tick",
    "markEvidencePathComplete(completionContext.path);",
    "evidenceScreen.style.gridTemplateRows=hasRequirements?'1fr 1fr':'1fr';",
    "function openPhotoCapture(step, sessionId)",
    "function openVideoCapture(step, sessionId)",
    "function openAudioCapture(step, sessionId)",
    "function openTextCapture(step, sessionId)"
]
